create_order_preview.code:
var response = await client.OrderPreviews.CreateOrderPreviewAsync(new Dictionary<string, object?>
{
    ["customer_id"] = 512, ["delivery_type"] = "shipping",
    ["products"] = new[] { new Dictionary<string, object?> { ["product_id"] = 101, ["quantity"] = 2 } },
});
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
var order = (IReadOnlyDictionary<string, object?>)body["order"]!;
var session = (IReadOnlyDictionary<string, object?>)order["session"]!;
var totals = (IReadOnlyDictionary<string, object?>)order["totals"]!;
Console.WriteLine($"{session["session_id"]} {session["expires_at"]} {totals["grand_total"]} {totals["due"]}");

